fn checked_total(items: &[u64], limit: u64) -> Option<u64> {
    let mut total = 0_u64;
    for value in items {
        total = total.checked_add(*value)?;
        if total > limit { return None; }
    }
    Some(total)
}

fn keep_prefix(previous: &[u32], desired: &[u32]) -> bool {
    desired.starts_with(previous)
}

// Reject arithmetic overflow before accepting a requested allocation.
// A valid prefix permits append; divergence requires rebuilding state.

def choose_ready(tasks, capacity):
    ready = []
    for task in tasks:
        if task["cancelled"]:
            continue
        if len(ready) == capacity:
            break
        ready.append(task["id"])
    return ready

records = [{"id": "alpha", "cancelled": False},
           {"id": "beta", "cancelled": True},
           {"id": "gamma", "cancelled": False}]
assert choose_ready(records, 2) == ["alpha", "gamma"]
